insert into public.patches (id, position, target, summary, code)
select id, position, target, summary, code from jsonb_populate_recordset(null::public.patches, $j$[{"id":"Patch F.1","position":1,"target":"00.A §2.1","summary":"Advisory flock before unlinking UDS socket","code":"// flock(fd, LOCK_EX | LOCK_NB) before unlink(sock_path)"},{"id":"Patch F.2","position":2,"target":"00.B §1.2","summary":"Linux cgroup.kill & AppArmor wrapper profile","code":"# /etc/apparmor.d/usr.lib.geminiforge.gf-bwrap-helper"},{"id":"Patch F.3","position":3,"target":"01.C §2.1","summary":"Hardened DuckDB forensic view isolation","code":"SET enable_external_access = false; SET lock_configuration = true;"},{"id":"Patch F.4","position":4,"target":"02.A §3.2","summary":"Split VRAM/RAM MoE Admission calculation","code":"VRAM_req = (P_shared + P_experts_vram) * b_quant <= VRAM_avail"},{"id":"Patch F.5","position":5,"target":"02.C §4.1","summary":"Stateless AT-SPI2 D-Bus drainage & HWND UIA","code":"// zbus AT-SPI2 event drainage preventing Qt6 hangs (cua#4894)"},{"id":"Patch F.6","position":6,"target":"05.C §1.1","summary":"Zero-Token SQLite Pre-Wake Gate (<0.1ms)","code":"SELECT EXISTS(SELECT 1 FROM tasks WHERE assignee = ?1 AND status = 'PENDING');"}]$j$::jsonb);
